-- Venue Live Guest "Lamaran Istana Timur". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara istana), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'istana', 'Lamaran Istana Timur', 'istana', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 157, 'center 38%',
  $t${"name":"Lamaran Istana Timur","orn":"diamond","ui":{"ivory":"#FBF6EE","white":"#FFFFFF","soft":"#F1E2C8","soft2":"#D9A93F","accent":"#8E1F3A","deep":"#1E1A2E","ink":"#2A2233","mute":"#8A7A6A","line":"#EBDCC0","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFBF3","ink":"#2A2233","accent":"#8E1F3A","gold":"#D9A93F","leaf":"#F1E2C8","hbg":"rgba(251,246,238,.94)","hline":"#D9A93F","motif":"diamond"},"hud":{"bg":"rgba(30,26,46,.9)","acc":"#F2D27A","on":"#1E1A2E"},"scr":{"wine":"#1E1A2E","veil":"251,246,238"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'istana');
